-- public.faith_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.faith_refusal(p_world uuid, p_uid uuid, p_action text, p_target jsonb)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare p player; pc placed; rest double precision; med double precision; v_statue item;
        v_way text; v_step path_step;
begin
  select * into p from player where world_id = p_world and uid = p_uid;

  if p_action = 'pray' then
    select * into pc from placed where world_id = p_world and id = (p_target->>'id')::bigint
      and kind = 'furniture';
    if not found or not is_altar(pc) then return 'It is gone.'; end if;
    if not near_piece(p_world, p_uid, pc) then return 'Stand at the altar.'; end if;
    rest := prayer_rest() - extract(epoch from (now() - coalesce(p.prayed_at, 'epoch')));
    if rest > 0 then
      return 'Prayer cooldown: ' || round(prayer_rest() / 60) || ' min. ' || ceil(rest / 60) || ' min left.';
    end if;
    return null;

  elsif p_action = 'pray_statue' then
    -- A patron's statue in the pack, anywhere, by a follower of its patron, at the altar's wait (`statuePrayRefusal`).
    v_statue := carried(p_world, p_uid, target_item(p_target));
    if v_statue.id is null or statue_patron(v_statue.def) is null then return 'It is gone.'; end if;
    if p.patron is distinct from statue_patron(v_statue.def) then return statue_followers(v_statue.def); end if;
    rest := prayer_rest() - extract(epoch from (now() - coalesce(p.prayed_at, 'epoch')));
    if rest > 0 then
      return 'Prayer cooldown: ' || round(prayer_rest() / 60) || ' min. ' || ceil(rest / 60) || ' min left.';
    end if;
    return null;

  elsif p_action = 'meditate' then
    if pack_count(p_world, p_uid, 'rug') <= 0 then return 'Need a rug.'; end if;
    rest := sit_rest() - extract(epoch from (now() - coalesce(p.sat_at, 'epoch')));
    if rest > 0 then
      return 'Sat already: next sitting in ' || ceil(rest / 60) || ' min.';
    end if;
    return null;

  elsif p_action = 'choose_path' then
    if p.way is not null then
      return 'Path already chosen.';
    end if;
    med := skill_of(p_world, p_uid, meditation_skill());
    if med < choose_at() then
      return 'Need meditation ' || round(choose_at()) || '.';
    end if;
    v_way := p_target->>'material';
    if v_way is null or not exists (select 1 from path_def where id = v_way) then
      return 'Choose a path.';
    end if;
    return null;

  elsif p_action = 'use_ability' then
    v_step := ability_of(p_world, p_uid, p_target->>'material');
    if v_step.path is null then return 'Not known.'; end if;
    rest := v_step.rest - extract(epoch from (now()
      - coalesce((p.used_at->>v_step.ability)::timestamptz, 'epoch')));
    if rest > 0 then
      return v_step.name || ': ready in ' || ceil(rest / 60) || ' min.';
    end if;
    return null;
  end if;
  return null;
end $function$
